const cmdOut = $input.first().json;
const raw    = (cmdOut.stdout || '').trim();

let settings = {};
try {
  const parsed = JSON.parse(raw);
  if (parsed && typeof parsed === 'object') settings = parsed;
} catch(e) {}

settings.paths          = settings.paths          || {};
settings.paths.watchDir = settings.paths.watchDir || '/host/Volumes/alaaMac/driverr/taxi/newcode';
settings.paths.tempBase = settings.paths.tempBase || '/host/Volumes/alaaMac/driverr/taxi/tmp_extract';
settings.paths.logFile  = settings.paths.logFile  || '/host/Volumes/alaaMac/driverr/taxi/sync_results.log';

if (!settings.paths.codeDirs || !Array.isArray(settings.paths.codeDirs)) {
  settings.paths.codeDirs = settings.paths.codeDir
    ? [settings.paths.codeDir]
    : ['/host/Volumes/alaaMac/driverr/taxi/code'];
}
settings.paths.codeDirs = settings.paths.codeDirs.filter(
  d => typeof d === 'string' && d.trim().length > 0
);

settings.explicitPaths               = settings.explicitPaths               || {};
settings.smartMatch                  = settings.smartMatch                  || {};
settings.archiveHandling             = settings.archiveHandling             || {};
settings.archiveHandling.supportedTypes  = settings.archiveHandling.supportedTypes  || [];
settings.archiveHandling.macJunkPatterns = settings.archiveHandling.macJunkPatterns || [];

return [{ json: { settings } }];

const item = $("Watch newcode Folder").first();

const sourcePath =
  item.json.path        ||
  item.json.watchedFile ||
  item.json.filePath    ||
  item.json.fileName    ||
  '';

if (!sourcePath) {
  throw new Error('No file path. Raw: ' + JSON.stringify(item.json));
}

const parts    = sourcePath.split('/');
const fileName = parts[parts.length - 1];

return [{ json: {
  sourcePath,
  fileName,
  triggerTimestamp: new Date().toISOString()
}}];

const item     = $input.first();
const settings = $('Parse Settings').first().json.settings;
const fileName = item.json.fileName || '';
const lower    = fileName.toLowerCase();

const supportedTypes = (settings.archiveHandling || {}).supportedTypes || [];
let archiveType = null;

for (const t of supportedTypes) {
  if (lower.endsWith(t.ext)) {
    archiveType = t.type;
    break;
  }
}

return [{ json: {
  ...item.json,
  isArchive:   archiveType !== null ? 'true' : 'false',
  archiveType: archiveType || ''
}}];

const item     = $input.first();
const settings = $('Parse Settings').first().json.settings;

if (!settings || !settings.paths || !settings.paths.tempBase) {
  throw new Error('settings.paths.tempBase undefined');
}

const { sourcePath, fileName, archiveType } = item.json;

const TEMP_BASE    = settings.paths.tempBase;
const safeFileName = fileName.replace(/[^a-zA-Z0-9._-]/g, '_');
const tempDir      = TEMP_BASE + '/' + safeFileName + '_' + Date.now();

function bEsc(s) {
  return String(s)
    .replace(/\\/g, '\\\\')
    .replace(/"/g,  '\\"')
    .replace(/`/g,  '\\`')
    .replace(/\$/g, '\\$');
}

const eSrc = bEsc(sourcePath);
const eTmp = bEsc(tempDir);
let extractCmd = '';

if (archiveType === 'zip') {
  extractCmd = 'mkdir -p "' + eTmp + '"'
    + ' && unzip -o "' + eSrc + '" -d "' + eTmp + '"'
    + ' -x "__MACOSX/*" "*/.__*" "**/.DS_Store"'
    + ' ; find "' + eTmp + '" -name "._*" -delete'
    + ' ; find "' + eTmp + '" -name ".DS_Store" -delete'
    + ' ; rm -rf "' + eTmp + '/__MACOSX"';
} else if (archiveType === 'tar.gz') {
  extractCmd = 'mkdir -p "' + eTmp + '" && tar -xzf "' + eSrc + '" -C "' + eTmp + '"'
    + ' --exclude="._*" --exclude=".DS_Store" --exclude="__MACOSX"';
} else if (archiveType === 'tar.bz2') {
  extractCmd = 'mkdir -p "' + eTmp + '" && tar -xjf "' + eSrc + '" -C "' + eTmp + '"'
    + ' --exclude="._*" --exclude=".DS_Store" --exclude="__MACOSX"';
} else if (archiveType === 'tar.xz') {
  extractCmd = 'mkdir -p "' + eTmp + '" && tar -xJf "' + eSrc + '" -C "' + eTmp + '"'
    + ' --exclude="._*" --exclude=".DS_Store" --exclude="__MACOSX"';
} else if (archiveType === 'tar') {
  extractCmd = 'mkdir -p "' + eTmp + '" && tar -xf "' + eSrc + '" -C "' + eTmp + '"'
    + ' --exclude="._*" --exclude=".DS_Store" --exclude="__MACOSX"';
} else if (archiveType === 'gz') {
  const baseName = bEsc(fileName.replace(/\.gz$/i, ''));
  extractCmd = 'mkdir -p "' + eTmp + '" && gunzip -c "' + eSrc + '" > "' + eTmp + '/' + baseName + '"';
} else if (archiveType === '7z') {
  extractCmd = 'mkdir -p "' + eTmp + '" && 7z x "' + eSrc + '" -o"' + eTmp + '"'
    + ' -x!"__MACOSX" -x!"._*" -x!".DS_Store"';
} else if (archiveType === 'rar') {
  extractCmd = 'mkdir -p "' + eTmp + '" && unrar x "' + eSrc + '" "' + eTmp + '/"'
    + ' -x"._*" -x".DS_Store" -x"__MACOSX\\\\*"';
} else {
  extractCmd = 'mkdir -p "' + eTmp + '" && cp "' + eSrc + '" "' + eTmp + '/"';
}

return [{ json: { ...item.json, tempDir, extractCmd }}];

const archiveInfo = $('Build Extract Command').first().json;
const settings    = $('Parse Settings').first().json.settings;
const cmdOut      = $input.first().json;
const stdout      = cmdOut.stdout || '';
const tempDir     = archiveInfo.tempDir;

const macJunkPatterns = (settings.archiveHandling || {}).macJunkPatterns || [];

function isMacJunk(filePath) {
  const parts = filePath.split('/');
  const name  = parts[parts.length - 1];
  for (const pattern of macJunkPatterns) {
    if (pattern.endsWith('*')) {
      const prefix = pattern.slice(0, -1);
      if (name.startsWith(prefix)) return true;
    } else {
      if (parts.some(p => p === pattern)) return true;
      if (name === pattern) return true;
    }
  }
  return false;
}

const files = stdout
  .split('\n')
  .map(f => f.trim())
  .filter(f => f.length > 0 && !f.startsWith('find:'))
  .filter(f => !isMacJunk(f));

if (files.length === 0) {
  return [{ json: {
    sourcePath:       archiveInfo.sourcePath,
    fileName:         archiveInfo.fileName,
    triggerTimestamp: archiveInfo.triggerTimestamp,
    tempDir,
    extractedFrom:    archiveInfo.fileName
  }}];
}

return files.map(filePath => {
  const parts    = filePath.split('/');
  const fileName = parts[parts.length - 1];
  return { json: {
    sourcePath:       filePath,
    fileName,
    triggerTimestamp: archiveInfo.triggerTimestamp,
    tempDir,
    extractedFrom:    archiveInfo.fileName
  }};
});

const item     = $input.first();
const fileName = item.json.fileName || '';

const JUNK_NAMES = ['.DS_Store', 'Thumbs.db', 'desktop.ini', '.localized'];
if (JUNK_NAMES.includes(fileName) || fileName.startsWith('._')) {
  return [];
}

return [{ json: {
  sourcePath:       item.json.sourcePath       || '',
  fileName:         fileName,
  triggerTimestamp: item.json.triggerTimestamp || new Date().toISOString(),
  extractedFrom:    item.json.extractedFrom    || null,
  tempDir:          item.json.tempDir          || null
}}];

// ══════════════════════════════════════════════════════════
// Resolve Scenario
// Explicit paths + Smart Match run TOGETHER in one step.
//
// SCENARIO 1 — file found in codeDirs (smart match) and no
//              explicit path, OR explicit path == smart path
//              → overwrite in-place, delete from newcode
//
// SCENARIO 2 — NOT found in codeDirs, but has explicit path
//              → copy to explicit destination, delete from newcode
//
// SCENARIO 3 — found in codeDirs AND has explicit path,
//              but the two paths DIFFER
//              → copy to explicit dest, delete from OLD
//              codeDirs location AND newcode
//
// MISSING     — no match anywhere
//              → log error, delete from newcode
// ══════════════════════════════════════════════════════════

const fileInfo   = $('Normalize File Info').first().json;
const settings   = $('Parse Settings').first().json.settings;
const cmdOut     = $input.first().json;
const stdout     = cmdOut.stdout || '';

if (!settings || !settings.paths) throw new Error('settings.paths undefined');

const fileName   = fileInfo.fileName   || '';
const sourcePath = fileInfo.sourcePath || '';
const NEWCODE_DIR = settings.paths.watchDir;
const LOG_FILE    = settings.paths.logFile;

// ── Helper functions ─────────────────────────────────────
function bEsc(s) {
  return String(s)
    .replace(/\\/g, '\\\\')
    .replace(/"/g,  '\\"')
    .replace(/`/g,  '\\`')
    .replace(/\$/g, '\\$');
}

function logLine(msg) {
  const COLOR = msg.startsWith('SUCCESS') ? '\\033[0;32m'
              : msg.startsWith('WARNING') ? '\\033[0;33m'
              : '\\033[0;31m';
  const RESET = '\\033[0m';
  return `printf '%b\\n' "${COLOR}$(date -u +%Y-%m-%dT%H:%M:%SZ) ${bEsc(msg)}${RESET}" >> "${bEsc(LOG_FILE)}"`;
}

// ── 1. Explicit Paths lookup ─────────────────────────────
const rawExplicit      = settings.explicitPaths || {};
const explicitFiles    = rawExplicit.files    || {};
const explicitPatterns = rawExplicit.patterns || [];

function wildcardToRegex(pattern) {
  const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  return new RegExp('^' + escaped.replace(/\*/g, '.*') + '$', 'i');
}

let explicitDest = explicitFiles[fileName] || null;
if (!explicitDest) {
  for (const rule of explicitPatterns) {
    if (!rule.match || !rule.destinationFolder) continue;
    const regex = wildcardToRegex(rule.match);
    if (regex.test(fileName)) {
      explicitDest = rule.destinationFolder.replace(/\/$/, '') + '/' + fileName;
      break;
    }
  }
}

// ── 2. Smart Match ───────────────────────────────────────
const sm          = settings.smartMatch || {};
const MIN_SCORE   = sm.minScore   !== undefined ? sm.minScore   : 50;
const HIGH_CONF   = sm.highConf   !== undefined ? sm.highConf   : 90;
const AMBIG_DELTA = sm.ambigDelta !== undefined ? sm.ambigDelta : 8;

function normalize(name) {
  return name.toLowerCase().replace(/[-_\s]+/g, '').replace(/\.[^.]+$/, '');
}

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, (_, i) => [i]);
  for (let j = 1; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i-1] === b[j-1]
        ? dp[i-1][j-1]
        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
    }
  }
  return dp[m][n];
}

function simScore(a, b) {
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 100;
  return Math.round((1 - levenshtein(a, b) / maxLen) * 100);
}

const normalizedName = normalize(fileName);

const allFiles = stdout
  .split('\n')
  .map(f => f.trim())
  .filter(f => f.length > 0 && !f.startsWith('find:'));

const scored = allFiles.map(filePath => {
  const parts = filePath.split('/');
  const name  = parts[parts.length - 1];
  const nc    = normalize(name);
  let score = 0, matchType = 'none';
  if (name === fileName) {
    score = 100; matchType = 'exact';
  } else if (name.toLowerCase() === fileName.toLowerCase()) {
    score = 92;  matchType = 'case_insensitive';
  } else {
    score = Math.round(simScore(normalizedName, nc) * 0.85);
    matchType = 'fuzzy';
  }
  return { filePath, name, score, matchType };
});

const candidates = scored
  .filter(c => c.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score);

let smartDest = null, smartScore = null, smartMatchType = null;

if (candidates.length > 0) {
  const best         = candidates[0];
  const closeMatches = candidates.filter(c => best.score - c.score <= AMBIG_DELTA);
  const isAmbiguous  = closeMatches.length > 1 && best.score < HIGH_CONF;
  if (!isAmbiguous) {
    smartDest      = best.filePath;
    smartScore     = best.score;
    smartMatchType = best.matchType;
  }
}

// ── 3. Determine scenario ────────────────────────────────
let scenario, dest, deleteOldPath;

if (smartDest && (!explicitDest || smartDest === explicitDest)) {
  // SCENARIO 1 — file already exists in codeDirs at the right place
  scenario     = 'scenario1';
  dest         = smartDest;
  deleteOldPath = null;

} else if (!smartDest && explicitDest) {
  // SCENARIO 2 — new file, put it where explicit says
  scenario     = 'scenario2';
  dest         = explicitDest;
  deleteOldPath = null;

} else if (smartDest && explicitDest && smartDest !== explicitDest) {
  // SCENARIO 3 — file moved to a new path, clean old location
  scenario     = 'scenario3';
  dest         = explicitDest;
  deleteOldPath = smartDest;

} else {
  // MISSING — no mapping anywhere
  scenario     = 'missing';
  dest         = null;
  deleteOldPath = null;
}

// ── 4. Build shell command ───────────────────────────────
const fileToDelete = fileInfo.extractedFrom
  ? NEWCODE_DIR + '/' + fileInfo.extractedFrom
  : sourcePath;

const eSrc       = bEsc(sourcePath);
const eFileToDel = bEsc(fileToDelete);
const eFileName  = bEsc(fileName);

let copyCmd;

if (scenario === 'missing') {
  copyCmd = [
    `echo "MISSING: ${eFileName} — no match in codeDirs, no explicit path"`,
    logLine('MISSING|File:' + fileName + '|Reason:NoMatchAnywhere'),
    `rm -f "${eFileToDel}"`,
    `echo "Removed from newcode."`
  ].join('\n');

} else {
  const eDest          = bEsc(dest);
  const deleteOldLine  = deleteOldPath
    ? `rm -f "${bEsc(deleteOldPath)}"`
    : '# scenario1/2 — no old location to remove';
  const scenarioLabel  = scenario.toUpperCase();
  const logSuccess     = scenario === 'scenario1'
    ? logLine('SUCCESS|SCENARIO1|File:' + fileName + '|Dest:' + dest + '|SmartScore:' + smartScore + '|MatchType:' + smartMatchType)
    : scenario === 'scenario2'
      ? logLine('SUCCESS|SCENARIO2|File:' + fileName + '|Dest:' + dest + '|Type:NewFile')
      : logLine('SUCCESS|SCENARIO3|File:' + fileName + '|Dest:' + dest + '|DeletedOld:' + deleteOldPath);

  copyCmd = `set -e
echo ">>> ${scenarioLabel} START <<<"
echo "File    : ${eFileName}"
echo "Source  : ${eSrc}"
echo "Dest    : ${eDest}"

if [ ! -f "${eSrc}" ]; then
  echo "WARNING: source not found: ${eSrc} (likely already processed by another trigger event)"
  ${logLine('WARNING|' + scenarioLabel + '|File:' + fileName + '|Reason:SourceNotFound_AlreadyProcessed')}
  exit 0
fi

mkdir -p "$(dirname "${eDest}")"

if cp -f -- "${eSrc}" "${eDest}"; then
  echo "Copy OK."
else
  echo "Copy FAILED."
  ${logLine('ERROR|' + scenarioLabel + '|File:' + fileName + '|Reason:CopyFailed')}
  exit 1
fi

${deleteOldLine}

if rm -f "${eFileToDel}"; then
  echo "Removed from newcode."
else
  echo "Warning: could not remove from newcode (already gone?)."
fi

${logSuccess}
echo ">>> ${scenarioLabel} SUCCESS <<<"
`;
}

return [{ json: {
  ...fileInfo,
  scenario,
  dest,
  smartDest,
  smartScore,
  smartMatchType,
  explicitDest,
  copyCmd
}}];

// Build a TARGETED and HIGHLY OPTIMIZED find command
const fileInfo = $('Normalize File Info').first().json;
const settings = $('Parse Settings').first().json.settings;

const fileName = fileInfo.fileName || '';
const dirs = settings.paths.codeDirs || [];

function esc(s) {
  return String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// فلترة المسارات عشان نتأكد مفيش مسار فاضي
const validDirs = dirs.filter(d => d.trim().length > 0);
const dirArgs = validDirs.map(d => '"' + esc(d) + '"').join(' ');

const safeFn  = esc(fileName);

// استخراج الاسم الأساسي للبحث الذكي
const base = fileName
  .replace(/\.[^.]+$/, '')
  .replace(/[^a-zA-Z0-9]/g, '')
  .substring(0, 10);

// 🔥 السرعة هنا: استبعاد الفولدرات الثقيلة اللي بتعمل شلل للبحث ومسارات النظام
const pruneExpr = "\\( -name 'node_modules' -o -name '.git' -o -name 'build' -o -name '.dart_tool' -o -name '.pub-cache' -o -name 'newcode' -o -name 'tmp_extract' -o -name '__MACOSX' \\) -prune -o";

// أمر بحث واحد ذكي بيشمل كل الاحتمالات
const searchName = base.length >= 3 ? `*${base}*` : safeFn;

// تجميع الأمر النهائي
const findCmd = `find ${dirArgs} -type d ${pruneExpr} -type f -iname "${searchName}" -print 2>/dev/null | sort -u | head -n 50`;

return [{ json: { ...fileInfo, findCmd } }];
